       "The Spanish Inquisition, an institution of the Spanish crown and the Church of that time, investigated many of them; several were punished in public ceremonies called autos de fe in Seville around 1559-1562.",
       "Some, including Casiodoro de Reina and Cipriano de Valera, fled abroad and lived in exile, leaving homes and relatives behind.",
